function diff(x, y) {
    const z = x - y;
    if (z >= 0) {
        return z;
    }
    return z * (-1);
}

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim();
    const s = input.split('\n')[0];

    const m = {};
    let char = 'a'.charCodeAt(0);
    for (let i = 1; i <= 26; i++) {
        m[String.fromCharCode(char)] = i;
        char++;
    }

    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        let a, b;
        if (i === 0) {
            a = diff(m[s[i]], m['a']);
            b = diff(a, 26);
        } else {
            a = diff(m[s[i]], m[s[i - 1]]);
            b = diff(a, 26);
        }
        if (a < b) {
            ans += a;
        } else {
            ans += b;
        }
    }

    console.log(ans);
}

